@endphp
<div x-data="{
    filtros: { q: '', categoria: [], estoque: null },
    exportando: false,
    produtos: [
        { nome: 'Caderno pontilhado A5', categoria: 'Cadernos', estoque: 'disponivel', preco: 39.9 },
        { nome: 'Caneta nanquim 0,3', categoria: 'Canetas', estoque: 'baixo', preco: 18.5 },
        { nome: 'Lápis 6B', categoria: 'Lápis', estoque: 'disponivel', preco: 7.5 },
        { nome: 'Régua de aço 30 cm', categoria: 'Réguas', estoque: 'esgotado', preco: 24 },
        { nome: 'Estojo de lona', categoria: 'Estojos', estoque: 'disponivel', preco: 59.9 },
        { nome: 'Pincel chato nº 8', categoria: 'Pincéis', estoque: 'baixo', preco: 12.9 },
    ],
    get linhas() {
        return this.produtos.filter((p) => (! this.filtros.categoria.length || this.filtros.categoria.includes(p.categoria))
            && (! this.filtros.estoque || this.filtros.estoque === p.estoque));
    },
    exportar() {
        this.exportando = true;
        const rotulo = { disponivel: 'Disponível', baixo: 'Estoque baixo', esgotado: 'Esgotado' };
        const aspas = String.fromCharCode(34);
        const celula = (valor) => aspas + String(valor).replaceAll(aspas, aspas + aspas) + aspas;
        const linhas = [['Produto', 'Categoria', 'Estoque', 'Preço (R$)'], ...this.linhas.map((p) => [p.nome, p.categoria, rotulo[p.estoque], p.preco.toFixed(2).replace('.', ',')])];
        const arquivo = new Blob([String.fromCharCode(0xFEFF) + linhas.map((linha) => linha.map(celula).join(';')).join(String.fromCharCode(13, 10))], { type: 'text/csv;charset=utf-8' });
        const link = Object.assign(document.createElement('a'), { href: URL.createObjectURL(arquivo), download: 'produtos.csv' });
        document.body.append(link); link.click(); link.remove();
        setTimeout(() => { URL.revokeObjectURL(link.href); this.exportando = false; }, 600);
        this.$dispatch('toast', { title: 'Planilha exportada', description: this.linhas.length + ' produtos em produtos.csv', variant: 'success' });
    },
}" class="w-full">
    <x-nui::filter x-model="filtros" :fields="[
        ['name' => 'categoria', 'label' => 'Categoria', 'icon' => $tag, 'options' => $categorias],
        ['name' => 'estoque', 'label' => 'Estoque', 'type' => 'single', 'options' => ['disponivel' => 'Disponível', 'baixo' => 'Estoque baixo', 'esgotado' => 'Esgotado']],
    ]">
        <x-slot:actions>
            <x-nui::button variant="secondary" size="sm" class="ml-auto" x-on:click="exportar()"
                x-bind:disabled="! linhas.length || exportando" x-bind:aria-busy="exportando.toString()">
                {!! $planilha !!}
                <span>Exportar para Excel</span>
                <span class="inline-grid place-items-center min-w-5 h-5 px-1.5 rounded-full bg-secondary-content/10 text-[0.6875rem] font-semibold tabular-nums" x-text="linhas.length" aria-hidden="true"></span>
            </x-nui::button>
        </x-slot:actions>
    </x-nui::filter>
</div>

